-- The AI gateway (#44): ai_call gains the gateway columns (task, latency, status, error code, input
-- hash, capture and matter ids, suspicious flag, idempotency key) as nullable or defaulted columns,
-- so the append-only table and the 0008 triggers are untouched. ai_call_result holds the validated
-- output of an idempotent call for 24 hours under FORCE RLS with ws_isolation.
CREATE TABLE "ai_call_result" (
	"id" uuid PRIMARY KEY DEFAULT app_uuid_v7() NOT NULL,
	"idempotency_key" text NOT NULL,
	"ai_call_id" uuid NOT NULL,
	"output" jsonb NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL
);
